/// <summary>Simulated web search tool that returns mock results for demonstration.</summary>
static class WebSearchTool
{
    [Description("Searches the web for a query and returns relevant result snippets.")]
    public static Task<string> SearchAsync(
        [Description("The search query string")] string query)
    {
        // In production, replace with a real search API (e.g., Bing Search API).
        var results = new[]
        {
            $"[1] Overview: '{query}' — Found comprehensive information covering history, key concepts, and recent developments. (source: wikipedia.org)",
            $"[2] News: '{query}' — Recent article from 2025 discussing breakthroughs and current trends in this area. (source: reuters.com)",
            $"[3] Research: '{query}' — Peer-reviewed study analyzing impacts, benefits, and future directions. (source: nature.com)",
        };

        var output = $"Search results for \"{query}\":\n{string.Join("\n", results)}";
        return Task.FromResult(output);
    }
}

/// <summary>Note-taking tool that stores research findings in memory.</summary>
sealed class Notepad
{
    private readonly List<Note> _notes = [];

    public IReadOnlyList<Note> Notes => _notes;

    [Description("Saves a research note with a title and body.")]
    public string SaveNote(
        [Description("A short descriptive title for the note")] string title,
        [Description("The body content of the note")] string body)
    {
        _notes.Add(new Note(title, body));
        return $"Note saved: \"{title}\" (total notes: {_notes.Count})";
    }

    [Description("Returns all saved research notes as a JSON array.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        return JsonSerializer.Serialize(_notes, new JsonSerializerOptions { WriteIndented = true });
    }
}

