 using System.ComponentModel;
 using System.Text.Json;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;

 // --- Configuration ---
 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running.");

 var modelId = "gpt-4o-mini-2024-07-18";

 // --- Build the chat client via MEAI abstraction ---
 IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
     .GetChatClient(modelId)
     .AsIChatClient();

 // --- Define tools ---
 var notepad = new Notepad();

 var tools = new List<AITool>
 {
     AIFunctionFactory.Create(
         WebSearchTool.SearchAsync,
         "web_search",
         "Searches the web for a query and returns a list of result snippets. Use this to research a topic."),
     AIFunctionFactory.Create(
         notepad.SaveNote,
         "save_note",
         "Saves a research note with a title and body. Use this to record key findings."),
     AIFunctionFactory.Create(
         notepad.GetNotes,
         "get_notes",
         "Returns all saved research notes. Use this to review collected findings before summarizing."),
 };

 // --- Create the agent ---
 var agent = new ChatClientAgent(
     chatClient,
     instructions: """
         You are a research agent. When given a topic:
         1. Use the web_search tool multiple times with varied queries to gather information.
         2. Use the save_note tool to record each key finding with a descriptive title.
         3. Use the get_notes tool to review everything you collected.
         4. Produce a well-structured summary of your research, citing the sources you found.
         Be thorough — search at least 3 different queries before summarizing.
         """,
     name: "ResearchAgent",
     description: "An agent that researches topics by searching the web and taking notes.",
     tools: tools);

 // --- Run the agent ---
 Console.WriteLine("=== Research Agent ===");
 Console.Write("Enter a topic to research: ");
 var topic = Console.ReadLine()?.Trim();

 if (string.IsNullOrEmpty(topic))
 {
     Console.WriteLine("No topic provided. Exiting.");
     return;
 }

 Console.WriteLine($"\nResearching \"{topic}\"...\n");

 var session = await agent.CreateSessionAsync();

 var runOptions = new ChatClientAgentRunOptions
 {
     ChatOptions = new ChatOptions
     {
         Temperature = 0f,
         MaxOutputTokens = 4096,
     },
 };

 await foreach (var update in agent.RunStreamingAsync(topic, session, runOptions))
 {
     Console.Write(update.Text);
 }

 Console.WriteLine();

 // Display collected notes
 Console.WriteLine("\n--- Research Notes ---");
 foreach (var note in notepad.Notes)
 {
     Console.WriteLine($"\n## {note.Title}");
     Console.WriteLine(note.Body);
 }

 // --- Tool implementations ---

 /// <summary>Simulated web search tool that returns mock results for demonstration.</summary>
 static class WebSearchTool
 {
     [Description("Searches the web for a query and returns relevant result snippets.")]
     public static Task<string> SearchAsync(
         [Description("The search query string")] string query)
     {
         // In production, replace with a real search API (e.g., Bing Search API).
         var results = new[]
         {
             $"[1] Overview: '{query}' — Found comprehensive information covering history, key concepts, and recent developments. (source: wikipedia.org)",
             $"[2] News: '{query}' — Recent article from 2025 discussing breakthroughs and current trends in this area. (source: reuters.com)",
             $"[3] Research: '{query}' — Peer-reviewed study analyzing impacts, benefits, and future directions. (source: nature.com)",
         };

         var output = $"Search results for \"{query}\":\n{string.Join("\n", results)}";
         return Task.FromResult(output);
     }
 }

 /// <summary>Note-taking tool that stores research findings in memory.</summary>
 sealed class Notepad
 {
     private readonly List<Note> _notes = [];

     public IReadOnlyList<Note> Notes => _notes;

     [Description("Saves a research note with a title and body.")]
     public string SaveNote(
         [Description("A short descriptive title for the note")] string title,
         [Description("The body content of the note")] string body)
     {
         _notes.Add(new Note(title, body));
         return $"Note saved: \"{title}\" (total notes: {_notes.Count})";
     }

     [Description("Returns all saved research notes as a JSON array.")]
     public string GetNotes()
     {
         if (_notes.Count == 0)
         {
             return "No notes saved yet.";
         }

         return JsonSerializer.Serialize(_notes, new JsonSerializerOptions { WriteIndented = true });
     }
 }

 record Note(string Title, string Body);
